import heapq

def match(orders):
    trades = []
    # order books: price -> list of [id, qty, arrival_seq]
    buy_heap = []  # max-heap by price: store (-price, seq, id)
    sell_heap = []  # min-heap by price: store (price, seq, id)

    order_info = {}  # id -> dict with side, price, qty (remaining), seq, active
    seq_counter = [0]

    def add_resting(oid, side, price, qty, seq):
        order_info[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def clean_buy_heap():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            info = order_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell_heap():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = order_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = order_info.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        oid = order[1]
        side = order[2]
        seq_counter[0] += 1
        seq = seq_counter[0]

        if typ == 'limit':
            price = order[3]
            qty = order[4]
        elif typ == 'ioc':
            price = order[3]
            qty = order[4]
        elif typ == 'market':
            qty = order[3]
            price = None

        remaining = qty

        if side == 'buy':
            clean_sell_heap()
            while remaining > 0 and sell_heap:
                sp, sseq, sid = sell_heap[0]
                if typ != 'market' and sp > price:
                    break
                sinfo = order_info[sid]
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                if sinfo['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    sinfo['active'] = False
                clean_sell_heap()

            if remaining > 0 and typ == 'limit':
                add_resting(oid, side, price, remaining, seq)
            else:
                if oid in order_info:
                    order_info[oid]['active'] = False
                else:
                    order_info[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}

        else:  # sell
            clean_buy_heap()
            while remaining > 0 and buy_heap:
                negbp, bseq, bid = buy_heap[0]
                bp = -negbp
                if typ != 'market' and bp < price:
                    break
                binfo = order_info[bid]
                trade_qty = min(remaining, binfo['qty'])
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                if binfo['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    binfo['active'] = False
                clean_buy_heap()

            if remaining > 0 and typ == 'limit':
                add_resting(oid, side, price, remaining, seq)
            else:
                if oid in order_info:
                    order_info[oid]['active'] = False
                else:
                    order_info[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}

    return trades

